-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.cellar_flight_refusal(p_world uuid, p_building integer, p_x integer, p_y integer, p_side text, p_down boolean, p_spiral boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare c cellar_tile; v_fx int; v_fy int;
begin
  c := cellar_at(p_world, p_x, p_y);
  if c.world_id is null and not p_down then return 'Stairs and ladders need an upper storey: plan one first.'; end if;
  if coalesce(c.dug, 0) < cellar_depth() then
    return 'Dig the cellar first: ' || metres(coalesce(c.dug, 0)) || ' m of ' || metres(cellar_depth()) || ' m dug.';
  end if;
  -- A glasshouse's field is cleared before anything is planned over it (`glasshouse.ts`).
  if land_tile(p_world, p_x, p_y) = tile_id('Field') then
    return 'Field here: clear it first.';
  end if;
  -- A spiral staircase comes down on its own tile, which is dug.
  if p_spiral then return null; end if;
  if p_side is null then return 'Choose the side to climb from.'; end if;
  v_fx := p_x + case p_side when 'w' then -1 when 'e' then 1 else 0 end;
  v_fy := p_y + case p_side when 'n' then -1 when 's' then 1 else 0 end;
  if (cellar_at(p_world, v_fx, v_fy)).building is distinct from p_building or not cellar_done(p_world, v_fx, v_fy) then
    return 'Foot would land on ' || v_fx || ',' || v_fy || ': no cellar dug there.';
  end if;
  return null;
end $function$
